def minimal_string(s):
    from collections import deque

    t = deque()
    stack = []

    for char in s:
        if not stack or char >= stack[-1]:
            stack.append(char)
        else:
            while stack and char < stack[-1]:
                t.append(stack.pop())
            stack.append(char)

    while stack:
        t.append(stack.pop())

    return ''.join(t)

