from sys import stdin, stdout

def min_lexicographical_string(s):
    stack = []
    result = []

    for char in s:
        stack.append(char)

    while stack:
        top_char = stack.pop()
        if not result or top_char <= result[-1]:
            result.append(top_char)
        else:
            while result and top_char < result[-1]:
                stack.append(result.pop())
            result.append(top_char)

    return ''.join(result)

if __name__ == "__main__":
    input_str = stdin.read().strip()
    output_str = min_lexicographical_string(input_str)
    stdout.write(output_str + '\n')
